def longestWord(s: str) -> str:
    if not s:
        return ""
    longest = ""
    current = ""
    for ch in s:
        if ch == " ":
            if current and len(current) > len(longest):
                longest = current
            current = ""
        else:
            current += ch
    if current and len(current) > len(longest):
        longest = current
    return longest

def main():
    tests = [
        ("hello world", "hello"),
        ("the quick brown fox jumps over the lazy dog", "quick"),
        ("a bb ccc dddd eeee fff gg h", "dddd"),
        ("", ""),
        ("single", "single"),
        ("  leading  spaces  ", "leading"),
        ("tie first second", "first"),
        ("end with space ", "with"),
        ("a", "a"),
        ("multiple    spaces   between", "multiple")
    ]
    for x, expected in tests:
        y = longestWord(x)
        print(y)

if __name__ == "__main__":
    main()

