#include <stdio.h>
#include <string.h>
#include <stdbool.h>

char* longestWord(const char* s) {
    if (s == NULL || s[0] == '\0') {
        return "";
    }

    const char* start = NULL;
    const char* end = NULL;
    const char* best_start = NULL;
    size_t best_len = 0;
    bool in_word = false;

    for (const char* p = s; *p != '\0'; p++) {
        if (*p == ' ') {
            if (in_word) {
                size_t current_len = p - start;
                if (current_len > best_len) {
                    best_len = current_len;
                    best_start = start;
                }
                in_word = false;
            }
        } else {
            if (!in_word) {
                start = p;
                in_word = true;
            }
        }
    }

    if (in_word) {
        size_t current_len = strlen(s) - (start - s);
        if (current_len > best_len) {
            best_len = current_len;
            best_start = start;
        }
    }

    static char result[256];
    if (best_start != NULL) {
        strncpy(result, best_start, best_len);
        result[best_len] = '\0';
    } else {
        result[0] = '\0';
    }

    return result;
}

int main() {
    printf("Test 1: '%s'\n", longestWord("hello world"));
    printf("Test 2: '%s'\n", longestWord("the quick brown fox jumps over the lazy dog"));
    printf("Test 3: '%s'\n", longestWord(""));
    printf("Test 4: '%s'\n", longestWord("a bb ccc dd eeee"));
    printf("Test 5: '%s'\n", longestWord("  leading and trailing spaces  "));
    printf("Test 6: '%s'\n", longestWord("single"));
    printf("Test 7: '%s'\n", longestWord("tie first second third"));
    printf("Test 8: '%s'\n", longestWord("multiple    spaces   between   words"));

    return 0;
}

