public class Solution {
    public static String longestWord(String s) {
        if (s.isEmpty()) {
            return "";
        }
        String longest = "";
        int start = 0;
        int n = s.length();
        while (start < n) {
            while (start < n && s.charAt(start) == ' ') {
                start++;
            }
            if (start >= n) {
                break;
            }
            int end = start;
            while (end < n && s.charAt(end) != ' ') {
                end++;
            }
            String word = s.substring(start, end);
            if (word.length() > longest.length()) {
                longest = word;
            }
            start = end;
        }
        return longest;
    }

    public static void main(String[] args) {
        // Test 1: Normal case
        System.out.println(longestWord("hello world programming"));
        // Test 2: Tie, return first
        System.out.println(longestWord("cat dog fish"));
        // Test 3: Empty string
        System.out.println(longestWord(""));
        // Test 4: Single word
        System.out.println(longestWord("solitary"));
        // Test 5: Multiple spaces and leading/trailing spaces
        System.out.println(longestWord("   multiple   spaces   between   words   "));
    }
}
